-- Anonymous links use one isolated capability, without opening the private schema.
create schema handover_capabilities; revoke all on schema handover_capabilities from public; grant usage on schema handover_capabilities to anon,authenticated; create function handover_capabilities.read(p_token text) returns jsonb language sql stable security definer set search_path='' as $$select private.handover_shared(p_token)$$; revoke all on function handover_capabilities.read(text) from public,anon,authenticated; grant execute on function handover_capabilities.read(text) to anon,authenticated; create or replace function public.handover_shared(p_token text) returns jsonb language sql stable security invoker set search_path='' as $$select handover_capabilities.read(p_token)$$;
